SqlDataAdapter da;
da = new SqlDataAdapter(strCmd, sqlCon);
DataSet ds = new DataSet();
da.Fill(ds, "Departments");
dataGridView1.DataSource = ds;
dataGridView1.DataMember = "Departments";
}
